#!/usr/bin/env python3
"""Launch cfo_kernel so package dirs win over sibling CLI scripts like close.py."""

from __future__ import annotations

import os
import sys
from pathlib import Path


def _kernel_root() -> Path:
    env = os.environ.get("CFO_KERNEL", "").strip()
    if env:
        return Path(env).resolve()
    here = Path(__file__).resolve()
    for parent in (here, *here.parents):
        candidate = parent / ".cfo"
        if (candidate / "cfo_kernel").is_dir() or (candidate / ".venv").is_dir():
            return candidate
    raise FileNotFoundError("could not find .cfo kernel from sidecar_boot.py")


def _computer_root() -> Path:
    env = os.environ.get("HARNESS_COMPUTER", "").strip()
    if env:
        return Path(env).resolve()
    here = Path(__file__).resolve()
    return here.parents[2]


def _prepare_path(kernel: Path, computer: Path) -> None:
    shim = computer / "cfo" / ".import-path"
    shim.mkdir(parents=True, exist_ok=True)
    for pkg in kernel.iterdir():
        if not pkg.is_dir() or not (pkg / "__init__.py").is_file():
            continue
        dest = shim / pkg.name
        if dest.is_symlink() or dest.exists():
            dest.unlink()
        dest.symlink_to(pkg)
    sys.path.insert(0, str(shim))
    if str(kernel) not in sys.path:
        sys.path.insert(1, str(kernel))
    os.environ["PYTHONPATH"] = os.pathsep.join([str(shim), str(kernel)])


def main() -> int:
    os.environ.pop("HARNESS_BOT", None)
    os.environ.setdefault("CFO_EVAL_PHASE", "operational")
    kernel = _kernel_root()
    computer = _computer_root()
    os.environ["CFO_KERNEL"] = str(kernel)
    os.environ["HARNESS_COMPUTER"] = str(computer)
    _prepare_path(kernel, computer)
    from cfo_kernel.__main__ import main as kernel_main

    return kernel_main(["--computer", str(computer), *sys.argv[1:]])


if __name__ == "__main__":
    raise SystemExit(main())

/**
 * Client Handle payloads for Source Bot wakes.
 * Harness core does not learn what an invoice is.
 */

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export interface SourceSendPayload {
  readonly from: string;
  readonly to: string;
  readonly toSlug: string;
  readonly profile: string;
  readonly prompt: string;
  readonly paths: readonly string[];
  readonly kind: "a2a_handoff";
  readonly mode: "async";
  readonly onBusy: "queue";
  readonly idempotencyKey: string;
}

export interface SourceHandleIntent {
  readonly fromSlug: string;
  readonly toSlug: string;
  readonly profile: string;
  readonly paths: readonly string[];
  readonly prompt: string;
  readonly idempotencyKey: string;
}

export function botIdForSlug(slug: string): string {
  return `bot_${slug.replace(/-/g, "_")}`;
}

export function toSendPayload(intent: SourceHandleIntent): SourceSendPayload {
  return {
    from: botIdForSlug(intent.fromSlug),
    to: botIdForSlug(intent.toSlug),
    toSlug: intent.toSlug,
    profile: intent.profile,
    prompt: intent.prompt,
    paths: intent.paths,
    kind: "a2a_handoff",
    mode: "async",
    onBusy: "queue",
    idempotencyKey: intent.idempotencyKey,
  };
}

export function parseSendPayload(value: unknown): SourceSendPayload | undefined {
  if (!isRecord(value)) {
    return undefined;
  }
  const row = value;
  if (
    typeof row.from !== "string" ||
    typeof row.to !== "string" ||
    typeof row.toSlug !== "string" ||
    typeof row.profile !== "string" ||
    typeof row.prompt !== "string" ||
    typeof row.kind !== "string" ||
    typeof row.mode !== "string" ||
    typeof row.onBusy !== "string" ||
    typeof row.idempotencyKey !== "string" ||
    !Array.isArray(row.paths)
  ) {
    return undefined;
  }
  const paths = row.paths.filter((item): item is string => typeof item === "string");
  if (paths.length !== row.paths.length) {
    return undefined;
  }
  if (row.kind !== "a2a_handoff" || row.mode !== "async" || row.onBusy !== "queue") {
    return undefined;
  }
  return {
    from: row.from,
    to: row.to,
    toSlug: row.toSlug,
    profile: row.profile,
    prompt: row.prompt,
    paths,
    kind: "a2a_handoff",
    mode: "async",
    onBusy: "queue",
    idempotencyKey: row.idempotencyKey,
  };
}

export function stripePacketHasNoInvoiceCandidate(packet: unknown): boolean {
  if (!isRecord(packet)) {
    return false;
  }
  return packet.invoice_candidates === 0;
}
